fn arccos(x: Vec<i8>) -> Vec<i8> {
    // Pre-allocate output Vec with the same length as input
    let mut result = Vec::with_capacity(x.len());

    // Transform each element according to the specification:
    // -1 -> 3
    //  0 -> 1 (any value in [0,3] is acceptable for inputs == 0)
    //  1 -> 0
    for value in x {
        let mapped = match value {
            -1 => 3,
             0 => 1,
             1 => 0,
             _ => panic!("Input values must be in [-1, 1], but got {}", value),
        };
        result.push(mapped);
    }

    result
}

